from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.lib import colors
import csv
p='/mnt/data/adaptive_affine_reconditioning.pdf'; s=getSampleStyleSheet(); doc=SimpleDocTemplate(p,pagesize=(595,842),rightMargin=52,leftMargin=52,topMargin=52,bottomMargin=52)
rows=list(csv.DictReader(open('/mnt/data/adaptive_affine_reconditioning_results.csv')))
story=[Paragraph('Cell-Centered Reconditioning of Dyadic Affine Oscillator Enclosures',s['Title']),Paragraph('Flyxion | Numerical research supplement | November 2026',s['Normal']),Spacer(1,14)]
paras=[('Scope','We subdivide the fixed but uncertain growth parameter a in [0.15,0.19] into one, two, or four closed subintervals. Each subinterval receives its own nominal trajectory, first parameter sensitivity, and outward-rounded interval remainder. The growth parameter remains fixed along each candidate trajectory. This is parameter-cell reconditioning, not a Lohner moving-frame state reconditioning algorithm.'),('System and certificate','The reduced real oscillator system is u\u2032 = au - u^3 - k(u-v), v\u2032 = av - v^3 - k(v-u), and J\u2032 = 2 c_A k^2 (u-v)^2. The experiment uses k=0.7, c_A=0.1, initial state (u,v,J)=(0.45,0.21,0), and h=0.025. Initial energy is 0.1, supply 0.01, basal demand 0.005, and resource floor 0.08. The conservative all-time test is E_0 - b H - sup J(H) >= E_*. This follows from nonnegative supply and nondecreasing J, provided the continuous-time state and J enclosures are valid.'),('Method and verification','For each cell, a midpoint expansion is propagated together with a remainder. The implementation uses exact rational arithmetic for polynomial interval operations, dyadic outward rounding to 40 bits, and a local Picard enclosure check. The reported width is the maximum summed coordinate width of a single cell, not the width of the union across cells. A valid global expenditure upper bound is the maximum of the individual cell bounds. The experiment inherits the local remainder construction of the preceding implementation; it does not independently establish a full machine-checked proof of all analytic assumptions.'),('Interpretation','At H=0.4, splitting into four cells reduces the maximum per-cell state width by 44.4%, while the global J upper bound decreases by about 0.4%. All tested cells pass the conservative resource-floor test. This does not demonstrate long-horizon moving affine-frame transport: nominal state intervals still suffer wrapping, and the benchmark remains a two-oscillator real subsystem.')]
for title,body in paras:story.extend([Paragraph(title,s['Heading2']),Paragraph(body,s['BodyText']),Spacer(1,8)])
story.append(Paragraph('Numerical results (40-bit dyadic rounding)',s['Heading2']))
data=[['H','Cells','Max cell width','Max J upper','Min energy lower']]
for r in rows:data.append([f"{float(r['horizon']):.1f}",r['cells'],f"{float(r['max_cell_affine_width']):.6f}",f"{float(r['max_J_upper']):.8f}",f"{float(r['minimum_prefix_energy_lower']):.6f}"])
t=Table(data,colWidths=[45,50,112,112,120],repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#dddddd')),('GRID',(0,0),(-1,-1),0.3,colors.grey),('FONTSIZE',(0,0),(-1,-1),8),('ALIGN',(0,0),(-1,-1),'CENTER'),('BOTTOMPADDING',(0,0),(-1,-1),5)]));story.append(t)
story.extend([Spacer(1,12),Paragraph('Next obligation',s['Heading2']),Paragraph('Replace parameter-cell subdivision with a genuinely moving affine state frame, and certify the nonlinear residual in the transported coordinates. Compare global hull widths and resource expenditure, not only individual cell widths.',s['BodyText'])]);doc.build(story);print(p)
